// the file holds the bytes 0123456
int a = open("f", O_RDONLY);
int b = dup(a);                 // same open-file entry as a
int c = open("f", O_RDONLY);    // a new entry, offset 0
char buf[2], x, y;
read(a, buf, 2);                // buf = '0','1'; shared offset is now 2
read(b, &x, 1);                 // x = '2', because the offset is shared
read(c, &y, 1);                 // y = '0', because c has its own offset
